const driver1 = $('Parse Drivers').item.json.driver1 || '';
const driver2 = $('Parse Drivers').item.json.driver2 || '';
const raceDate = $('Parse Drivers').item.json.race_date || '';
const isGeneral = driver1.toLowerCase() === 'general' || driver1 === '';
const isH2H = driver2 && driver2.toLowerCase() !== '' && !isGeneral;

// --- Odds data: extract top 5 drivers by tightest american odds ---
let oddsData = [];
try {
  oddsData = $('Get F1 Odds').all().map(i => i.json).flat() || [];
} catch(e) { oddsData = []; }

const driverOddsMap = {};
for (const event of oddsData) {
  for (const bookie of (event.bookmakers || [])) {
    for (const market of (bookie.markets || [])) {
      if (market.key === 'outrights') {
        for (const outcome of (market.outcomes || [])) {
          const name = outcome.name || '';
          if (!driverOddsMap[name]) driverOddsMap[name] = [];
          driverOddsMap[name].push(outcome.price);
        }
      }
    }
  }
}

const avg = arr => arr.length ? Math.round(arr.reduce((a,b) => a+b, 0) / arr.length) : null;
const driverAvgOdds = Object.entries(driverOddsMap).map(([name, prices]) => ({
  driver: name,
  avgOdds: avg(prices)
}));
driverAvgOdds.sort((a, b) => Math.abs(a.avgOdds) - Math.abs(b.avgOdds));
const top5 = driverAvgOdds.slice(0, 5);

let driver1Odds = null, driver2Odds = null;
if (!isGeneral) {
  const d1Lower = driver1.toLowerCase();
  const d2Lower = (driver2 || '').toLowerCase();
  for (const entry of driverAvgOdds) {
    const n = entry.driver.toLowerCase();
    if (n.includes(d1Lower) || d1Lower.includes(n)) driver1Odds = entry.avgOdds;
    if (isH2H && (n.includes(d2Lower) || d2Lower.includes(n))) driver2Odds = entry.avgOdds;
  }
}

// --- ESPN F1 News ---
let newsHeadlines = [];
try {
  const newsItems = $('ESPN F1 News').first().json?.articles || [];
  newsHeadlines = newsItems.slice(0, 5).map(a => a.headline || a.title || '').filter(Boolean);
} catch(e) { newsHeadlines = []; }

// --- ESPN F1 Scoreboard ---
let raceContext = {};
try {
  const espnData = $('ESPN F1 Scoreboard').first().json;
  const events = espnData?.events || [];
  if (events.length > 0) {
    const nextRace = events[0];
    const competition = nextRace?.competitions?.[0] || {};
    const competitors = competition?.competitors || [];
    raceContext = {
      raceName: nextRace?.name || '',
      shortName: nextRace?.shortName || '',
      venue: competition?.venue?.fullName || '',
      venueCity: competition?.venue?.address?.city || '',
      venueCountry: competition?.venue?.address?.country || '',
      status: nextRace?.status?.type?.description || '',
      date: nextRace?.date || '',
      gridPositions: competitors.slice(0, 10).map(c => ({
        driver: c.athlete?.displayName || c.team?.displayName || '',
        position: c.order || c.linescores?.[0]?.value || null,
        team: c.team?.displayName || ''
      }))
    };
  }
} catch(e) { raceContext = {}; }

return [{
  json: {
    driver1, driver2, race_date: raceDate,
    is_h2h: isH2H, is_general: isGeneral,
    driver1_odds: driver1Odds, driver2_odds: driver2Odds,
    top5_drivers: top5,
    news_headlines: newsHeadlines,
    race_context: raceContext
  }
}];
